import { inject } from "./styles";

/**
 * Knurl — the public wrapper around an engine. It dresses the host element,
 * makes the svg, owns the options every control shares, and only ever removes
 * what it added.
 */

export type Theme = "auto" | "light" | "dark";
export type Finish = "line" | "solid";

/** Options every control takes. */
export type BaseOptions = {
  /** `"auto"` follows the page: an ancestor with `.dark` or `data-theme="dark"`, then `color-scheme`. */
  theme?: Theme;
  /** `"line"`: hairlines on plates (default). `"solid"`: shaded sides, lit lids and a contact shadow. */
  finish?: Finish;
  /** The accessible name. Each control has an English default. */
  label?: string;
  disabled?: boolean;
  /** A form field name: the control writes its value to a native input that submits with the form. */
  name?: string;
};

export type Control<O> = {
  /** Changes options on the running control. A key set to `undefined` goes back to its default; a key left out stays. */
  update(options: O): void;
  /** Stops the control and removes what it added. Safe to call twice. */
  destroy(): void;
};

export type EngineContext = {
  host: HTMLElement;
  svg: SVGSVGElement;
  doc: Document;
};

export type Engine<O> = { update(options: O, prev: O): void; destroy(): void };

export type Spec<O extends BaseOptions> = {
  id: string;
  label: string;
  /** viewBox size; the control's height follows its width at this ratio. */
  vw: number;
  vh: number;
  /** Default CSS width in px when the host has none. */
  width: number;
  /** The control's own option names (beyond BaseOptions), so a wrapper can tell options from attributes. */
  keys: readonly string[];
  /** The option that makes it controlled in React: "value" or "checked". */
  controlKey?: "value" | "checked";
  mount(ctx: EngineContext, options: O): Engine<O>;
};

const NS = "http://www.w3.org/2000/svg";
const mounted = new WeakMap<Element, () => void>();

export const report = (err: unknown) => {
  if (typeof reportError === "function") reportError(err);
  else setTimeout(() => { throw err; });
};

/** Calls a consumer callback without letting it unwind the shared frame loop. */
export function emit<A extends unknown[]>(fn: ((...a: A) => void) | undefined, ...args: A) {
  if (typeof fn === "function") try { fn(...args); } catch (err) { report(err); }
}

export const BASE_KEYS = ["theme", "finish", "label", "disabled", "name"] as const;

/** A mount function, carrying what a wrapper needs to know about it. */
export type Mount<O> = ((el: HTMLElement, options?: O) => Control<O>) & {
  readonly id: string; readonly keys: readonly string[]; readonly ratio: string; readonly controlKey?: "value" | "checked";
};

export function define<O extends BaseOptions>(spec: Spec<O>): Mount<O> {
  const create = function create(el: HTMLElement, options?: O): Control<O> {
    if (typeof document === "undefined") throw new Error(`knurl: ${spec.id}() needs a DOM; call it in the browser once the element exists.`);
    if (!el || el.nodeType !== 1) throw new TypeError(`knurl: ${spec.id}() takes an element as its first argument.`);
    mounted.get(el)?.();

    let opts = { ...options } as O;
    const doc = el.ownerDocument;
    const root = el.getRootNode();
    inject(root.nodeType === 9 || "host" in root ? (root as Document | ShadowRoot) : doc);

    const owned = new Set<string>();
    const attr = (name: string, value: string | null) => {
      if (!owned.has(name) && el.hasAttribute(name)) return;
      if (value === null) { el.removeAttribute(name); owned.delete(name); }
      else { el.setAttribute(name, value); owned.add(name); }
    };
    let ownWidth = false;
    if (!el.style.width) { el.style.width = spec.width + "px"; ownWidth = true; }
    const dress = () => {
      attr("data-knurl-theme", opts.theme === "light" || opts.theme === "dark" ? opts.theme : null);
      attr("data-knurl-finish", opts.finish === "solid" ? "solid" : "line");
      attr("data-disabled", opts.disabled ? "" : null);
    };
    attr("data-knurl", spec.id);
    dress();

    const svg = doc.createElementNS(NS, "svg") as SVGSVGElement;
    svg.setAttribute("viewBox", `0 0 ${spec.vw} ${spec.vh}`);
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("focusable", "false");
    el.appendChild(svg);

    const engine = spec.mount({ host: el, svg, doc }, opts);
    // a press on the drawing keeps focus where the control put it (its native input), instead of on <body>
    const keepFocus = (e: MouseEvent) => { if (!(e.target instanceof HTMLInputElement || e.target instanceof HTMLButtonElement)) e.preventDefault(); };
    el.addEventListener("mousedown", keepFocus);

    let dead = false;
    const destroy = () => {
      if (dead) return;
      dead = true;
      if (mounted.get(el) === destroy) mounted.delete(el);
      engine.destroy();
      el.removeEventListener("mousedown", keepFocus);
      svg.remove();
      for (const n of owned) el.removeAttribute(n);
      owned.clear();
      if (ownWidth) { el.style.removeProperty("width"); if (!el.getAttribute("style")) el.removeAttribute("style"); }
    };
    mounted.set(el, destroy);

    return {
      update(next) {
        if (dead || !next) return;
        const prev = opts;
        const merged = { ...opts } as Record<string, unknown>;
        for (const k in next) {
          const v = (next as Record<string, unknown>)[k];
          if (v === undefined) delete merged[k]; else merged[k] = v;
        }
        opts = merged as O;
        dress();
        engine.update(opts, prev);
      },
      destroy,
    };
  };
  return Object.assign(create, { id: spec.id, keys: [...BASE_KEYS, ...spec.keys], ratio: `${spec.vw} / ${spec.vh}`, controlKey: spec.controlKey });
}

/** A visually hidden native input inside the host: keyboard, screen readers and forms come from the platform. */
export function nativeInput(ctx: EngineContext, attrs: Record<string, string>): HTMLInputElement {
  const i = ctx.doc.createElement("input");
  i.setAttribute("data-knurl-sr", "");
  for (const k in attrs) i.setAttribute(k, attrs[k]);
  ctx.host.appendChild(i);
  return i;
}

export const num = (v: unknown, d: number) => (typeof v === "number" && Number.isFinite(v) ? v : d);

/** Snaps v to min + k·step and clamps to [min, max]. */
export function snap(v: number, min: number, max: number, step: number) {
  if (max < min) [min, max] = [max, min];
  const s = step > 0 ? step : 0;
  let x = s ? min + Math.round((v - min) / s) * s : v;
  x = Math.max(min, Math.min(max, x));
  // trim float noise from the step
  if (!s) return x;
  const dec = Math.max(...[s, min].map((n) => (String(n).split(".")[1] ?? "").length));
  return Number(x.toFixed(Math.min(dec, 10)));
}

/** Remembers the host's own values of `names`; the returned function puts them back (or removes what it did not have). */
export function keepAttrs(host: HTMLElement, names: readonly string[]): () => void {
  const was = names.map((n) => [n, host.getAttribute(n)] as const);
  return () => { for (const [n, v] of was) if (v === null) host.removeAttribute(n); else host.setAttribute(n, v); };
}

/**
 * Knurl — the drawing maths every control shares, with no DOM.
 *
 * The camera and the hull-silhouette solids follow Hairline (MIT, Lucas
 * Marques); the four-tone side shading and the lofted solid follow Anatomy's
 * kit (MIT, wheresryan22). One solid yields every path both finishes need, so
 * "line" and "solid" differ only in CSS.
 *
 * World space: x and y on the ground, z up. Screen space: the control's own
 * viewBox. No perspective; parts are painted back to front by the caller.
 */

export type Vec2 = [number, number];
export type Vec3 = [number, number, number];

export const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
export const rad = (d: number) => (d * Math.PI) / 180;
export const r2 = (n: number) => Math.round(n * 100) / 100;

export const poly = (pts: readonly Vec2[]) =>
  pts.length < 2 ? "" : "M" + pts.map((p) => r2(p[0]) + " " + r2(p[1])).join("L") + "Z";
export const open = (pts: readonly Vec2[]) =>
  pts.length < 2 ? "" : "M" + pts.map((p) => r2(p[0]) + " " + r2(p[1])).join("L");
export const seg = (a: Vec2, b: Vec2) => `M${r2(a[0])} ${r2(a[1])}L${r2(b[0])} ${r2(b[1])}`;

/* ───── camera ───── */

/** An orthographic camera: azimuth and elevation in degrees, scale S, offset set by `fit`. */
export type Camera = { az: number; el: number; S: number; ox: number; oy: number };
export type Projector = (x: number, y: number, z: number) => Vec2;

export const camera = (az = 45, el = 30, S = 1): Camera => ({ az, el, S, ox: 0, oy: 0 });

export function proj(C: Camera): Projector {
  const a = rad(C.az), c = Math.cos(a), s = Math.sin(a), k = Math.sin(rad(C.el)), zf = Math.cos(rad(C.el));
  return (x, y, z) => [C.ox + C.S * (x * c - y * s), C.oy + C.S * ((x * s + y * c) * k - z * zf)];
}

/** World x/y under a screen point, on the ground plane at height z. */
export function unproj(C: Camera, sx: number, sy: number, z: number): Vec2 {
  const a = rad(C.az), c = Math.cos(a), s = Math.sin(a), k = Math.sin(rad(C.el)), zf = Math.cos(rad(C.el));
  const X = (sx - C.ox) / C.S, Y = ((sy - C.oy) / C.S + z * zf) / k;
  return [X * c + Y * s, -X * s + Y * c];
}

/** Centres the projected bounding box of `pts` on (cx, cy). With `w`/`h`, also scales it to fit that box. */
export function fit(C: Camera, pts: readonly Vec3[], cx: number, cy: number, w?: number, h?: number) {
  C.ox = 0; C.oy = 0;
  if (w && h) {
    C.S = 1;
    const b = bounds(proj(C), pts);
    C.S = Math.min(w / (b[1] - b[0]), h / (b[3] - b[2]));
  }
  const b = bounds(proj(C), pts);
  C.ox = cx - (b[0] + b[1]) / 2; C.oy = cy - (b[2] + b[3]) / 2;
}

function bounds(P: Projector, pts: readonly Vec3[]): [number, number, number, number] {
  let a = 1e9, b = -1e9, c = 1e9, d = -1e9;
  for (const p of pts) {
    const q = P(p[0], p[1], p[2]);
    a = Math.min(a, q[0]); b = Math.max(b, q[0]); c = Math.min(c, q[1]); d = Math.max(d, q[1]);
  }
  return [a, b, c, d];
}

/** Depth along the view: larger is nearer the viewer. Sort ascending to paint back to front. */
export function depth(C: Camera, x: number, y: number, z: number) {
  const a = rad(C.az);
  return (x * Math.sin(a) + y * Math.cos(a)) * Math.cos(rad(C.el)) + z * Math.sin(rad(C.el));
}

/* ───── rings: footprints sampled with outward normals ───── */

export type Sample = { u: number; v: number; nu: number; nv: number };
export type Ring = Sample[];

/** A rounded rectangle from (x0, y0) to (x1, y1), counter-clockwise, n samples per corner. */
export function rrect(x0: number, y0: number, x1: number, y1: number, r: number, n = 5): Ring {
  r = Math.max(0, Math.min(r, (x1 - x0) / 2, (y1 - y0) / 2));
  const out: Ring = [];
  for (const [cu, cv, a0] of [[x1 - r, y1 - r, 0], [x0 + r, y1 - r, 90], [x0 + r, y0 + r, 180], [x1 - r, y0 + r, 270]] as const)
    for (let k = 0; k <= n; k++) {
      const a = rad(a0 + (90 * k) / n), ca = Math.cos(a), sa = Math.sin(a);
      out.push({ u: cu + r * ca, v: cv + r * sa, nu: ca, nv: sa });
    }
  return out;
}

/** A circle about (cx, cy), counter-clockwise. `phase` turns where the samples start. */
export function circle(cx: number, cy: number, R: number, n = 48, phase = 0): Ring {
  const out: Ring = [];
  for (let k = 0; k < n; k++) {
    const a = phase + (k / n) * Math.PI * 2, ca = Math.cos(a), sa = Math.sin(a);
    out.push({ u: cx + R * ca, v: cy + R * sa, nu: ca, nv: sa });
  }
  return out;
}

/** Moves a ring by (dx, dy). */
export const shift = (r: Ring, dx: number, dy: number): Ring => r.map((q) => ({ ...q, u: q.u + dx, v: q.v + dy }));

/** Insets a ring along its normals (a negative `by` grows it). */
export const inset = (r: Ring, by: number): Ring => r.map((q) => ({ ...q, u: q.u - q.nu * by, v: q.v - q.nv * by }));

/** Monotone-chain convex hull. */
export function hull(input: readonly Vec2[]): Vec2[] {
  const pts = input.slice().sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  if (pts.length < 3) return pts;
  const x = (o: Vec2, a: Vec2, b: Vec2) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo: Vec2[] = [], up: Vec2[] = [];
  for (const p of pts) { while (lo.length > 1 && x(lo[lo.length - 2], lo[lo.length - 1], p) <= 0) lo.pop(); lo.push(p); }
  for (let i = pts.length - 1; i >= 0; i--) { const p = pts[i]; while (up.length > 1 && x(up[up.length - 2], up[up.length - 1], p) <= 0) up.pop(); up.push(p); }
  lo.pop(); up.pop();
  return lo.concat(up);
}

/** Whether a ground normal faces the camera: screen-down in world is (sin az, cos az). */
export const facing = (C: Camera) => {
  const a = rad(C.az), s = Math.sin(a), c = Math.cos(a);
  return (nu: number, nv: number) => nu * s + nv * c > 1e-6;
};

/** The light comes from the upper left of the screen and a little toward the viewer. 0 is darkest, 1 lightest. */
export const lighting = (C: Camera) => {
  const a = rad(C.az), s = Math.sin(a), c = Math.cos(a);
  // screen-left on the ground is (-c, s); toward the viewer is (s, c)
  let lu = -c * 0.85 + s * 0.5, lv = s * 0.85 + c * 0.5;
  const L = Math.hypot(lu, lv); lu /= L; lv /= L;
  return (nu: number, nv: number) => (nu * lu + nv * lv + 1) / 2;
};

/** The one cyclic run of indices whose flag is true, in ring order (the ring is assumed to have one such run). */
function runOf(flags: readonly boolean[]): number[] {
  const n = flags.length;
  let s = -1;
  for (let i = 0; i < n; i++) if (flags[i] && !flags[(i + n - 1) % n]) { s = i; break; }
  if (s < 0) return flags[0] ? flags.map((_, i) => i) : [];
  const out: number[] = [];
  for (let k = 0; k < n && flags[(s + k) % n]; k++) out.push((s + k) % n);
  return out;
}

/* ───── solids ───── */

export const SHADES = 4;

/**
 * Every path a solid needs, in both finishes:
 *  - `sil`: the filled silhouette (hull of the two rings), stroked as the outline;
 *  - `shades`: the visible side faces bucketed by how much light they catch (solid finish only);
 *  - `top`: the lid (solid finish only);
 *  - `crease`: the front run of the lid, where it meets the sides (both finishes).
 */
export type SolidPaths = { sil: string; shades: string[]; top: string; crease: string };

/**
 * A loft between a ring at z0 and a ring at z1 (same sample count; `top`
 * defaults to the bottom ring). Covers slabs, cylinders and tapered caps.
 */
export function loft(C: Camera, P: Projector, bottom: Ring, z0: number, z1: number, top: Ring = bottom): SolidPaths {
  const n = bottom.length, front = facing(C), light = lighting(C);
  const lo = bottom.map((q) => P(q.u, q.v, z0)), hi = top.map((q) => P(q.u, q.v, z1));
  const buckets: string[][] = Array.from({ length: SHADES }, () => []);
  const flags: boolean[] = [];
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    // the face between sample i and i+1: its normal is the mean of theirs
    const a = bottom[i], b = bottom[j];
    let nu = a.nu + b.nu, nv = a.nv + b.nv;
    const L = Math.hypot(nu, nv) || 1; nu /= L; nv /= L;
    const vis = front(nu, nv);
    flags.push(front(top[i].nu, top[i].nv));
    if (!vis || z1 - z0 < 1e-6) continue;
    const t = Math.min(SHADES - 1, Math.floor(light(nu, nv) * SHADES));
    buckets[t].push(poly([hi[i], hi[j], lo[j], lo[i]]));
  }
  return {
    sil: poly(hull(hi.concat(lo))),
    shades: buckets.map((b) => b.join("")),
    top: poly(hi),
    crease: open(runOf(flags).map((i) => hi[i])),
  };
}

/** A slab with a rounded footprint. */
export const slab = (C: Camera, P: Projector, x0: number, y0: number, x1: number, y1: number, r: number, z0: number, z1: number) =>
  loft(C, P, rrect(x0, y0, x1, y1, r), z0, z1);

/** An upright cylinder. */
export const cyl = (C: Camera, P: Projector, cx: number, cy: number, R: number, z0: number, z1: number, n = 40) =>
  loft(C, P, circle(cx, cy, R, n), z0, z1);

/**
 * A round bar between two world points, tapering from r0 to r1: its silhouette,
 * and the cap at `b` as an ellipse-ish polygon. For levers and stems that tilt.
 */
export function bar(P: Projector, a: Vec3, b: Vec3, r0: number, r1: number, n = 24): { sil: string; cap: string; capPts: Vec2[] } {
  const d: Vec3 = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const L = Math.hypot(d[0], d[1], d[2]) || 1;
  const w: Vec3 = [d[0] / L, d[1] / L, d[2] / L];
  // two unit vectors across the axis
  const ref: Vec3 = Math.abs(w[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  let u: Vec3 = [w[1] * ref[2] - w[2] * ref[1], w[2] * ref[0] - w[0] * ref[2], w[0] * ref[1] - w[1] * ref[0]];
  const ul = Math.hypot(u[0], u[1], u[2]); u = [u[0] / ul, u[1] / ul, u[2] / ul];
  const v: Vec3 = [w[1] * u[2] - w[2] * u[1], w[2] * u[0] - w[0] * u[2], w[0] * u[1] - w[1] * u[0]];
  const ring = (o: Vec3, r: number) =>
    Array.from({ length: n }, (_, k): Vec2 => {
      const t = (k / n) * Math.PI * 2, ct = Math.cos(t) * r, st = Math.sin(t) * r;
      return P(o[0] + u[0] * ct + v[0] * st, o[1] + u[1] * ct + v[1] * st, o[2] + u[2] * ct + v[2] * st);
    });
  const ra = ring(a, r0), rb = ring(b, r1);
  return { sil: poly(hull(ra.concat(rb))), cap: poly(rb), capPts: rb };
}

/* ───── marks on planes ───── */

/** A ring of radial ticks on the plane z: `count` ticks across `span` radians from `from`, every `every`-th long. */
export function radialTicks(P: Projector, cx: number, cy: number, R: number, z: number, count: number, from: number, span: number, every: number, short: number, long: number) {
  const out: string[] = [], major: string[] = [];
  for (let k = 0; k <= count; k++) {
    const a = from + (span * k) / count, ca = Math.cos(a), sa = Math.sin(a), l = k % every === 0 ? long : short;
    (k % every === 0 ? major : out).push(seg(P(cx + ca * R, cy + sa * R, z), P(cx + ca * (R - l), cy + sa * (R - l), z)));
  }
  return { minor: out.join(""), major: major.join("") };
}

/** An SVG `matrix()` that puts a local 2D frame (x right along `u`, y down along `v`, in world units) at `o` on a plane. */
export function planeMatrix(P: Projector, o: Vec3, u: Vec3, v: Vec3) {
  const p0 = P(o[0], o[1], o[2]);
  const pu = P(o[0] + u[0], o[1] + u[1], o[2] + u[2]);
  const pv = P(o[0] + v[0], o[1] + v[1], o[2] + v[2]);
  return `matrix(${r2(pu[0] - p0[0])} ${r2(pu[1] - p0[1])} ${r2(pv[0] - p0[0])} ${r2(pv[1] - p0[1])} ${r2(p0[0])} ${r2(p0[1])})`;
}

/** A ring laid flat at height z, as a closed path. */
export const flat = (P: Projector, ring: readonly Sample[], z: number) => poly(ring.map((q) => P(q.u, q.v, z)));

/** Short straight ticks along x on the plane z, from y0 to y0+len (major: to y0+long). */
export function rulerX(P: Projector, x0: number, x1: number, n: number, every: number, y0: number, len: number, long: number, z: number) {
  const minor: string[] = [], major: string[] = [];
  for (let k = 0; k <= n; k++) {
    const x = x0 + ((x1 - x0) * k) / n, m = k % every === 0;
    (m ? major : minor).push(seg(P(x, y0, z), P(x, y0 + (m ? long : len), z)));
  }
  return { minor: minor.join(""), major: major.join("") };
}

/* ───── convex solids in any orientation ───── */

export const add3 = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
export const sub3 = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
export const scale3 = (a: Vec3, k: number): Vec3 => [a[0] * k, a[1] * k, a[2] * k];
export const cross3 = (a: Vec3, b: Vec3): Vec3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
export const dot3 = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

/** A 3×3 rotation as three column vectors; compose with `turn`. */
export type Rot = [Vec3, Vec3, Vec3];
export const IDENT: Rot = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
/** Rotation about the world x, y or z axis by `a` radians. */
export function rot(axis: "x" | "y" | "z", a: number): Rot {
  const c = Math.cos(a), s = Math.sin(a);
  if (axis === "x") return [[1, 0, 0], [0, c, s], [0, -s, c]];
  if (axis === "y") return [[c, 0, -s], [0, 1, 0], [s, 0, c]];
  return [[c, s, 0], [-s, c, 0], [0, 0, 1]];
}
/** Applies a rotation to a vector. */
export const turn = (R: Rot, v: Vec3): Vec3 => add3(add3(scale3(R[0], v[0]), scale3(R[1], v[1])), scale3(R[2], v[2]));
/** `A` after `B`: the rotation that applies B, then A. */
export const compose = (A: Rot, B: Rot): Rot => [turn(A, B[0]), turn(A, B[1]), turn(A, B[2])];

/** The direction toward the viewer, in world space. */
export const toViewer = (C: Camera): Vec3 => {
  const a = rad(C.az), e = rad(C.el);
  return [Math.sin(a) * Math.cos(e), Math.cos(a) * Math.cos(e), Math.sin(e)];
};

/**
 * Any convex polyhedron, from its vertices and its faces (each a ring of
 * vertex indices, counter-clockwise seen from outside). Faces turned up
 * (normal z > 0.6) are lids; the rest are shaded in four tones by facing.
 * The crease is every edge shared by two visible faces, so a tilted box
 * reads in the line finish exactly as an upright slab does.
 */
export function poly3(C: Camera, P: Projector, verts: readonly Vec3[], faces: readonly number[][]): SolidPaths {
  const V = toViewer(C), light = lighting(C);
  const scr = verts.map((v) => P(v[0], v[1], v[2]));
  const buckets: string[][] = Array.from({ length: SHADES }, () => []);
  const tops: string[] = [];
  const vis: boolean[] = [];
  const edgeCount = new Map<string, number>();
  faces.forEach((f, i) => {
    const n = cross3(sub3(verts[f[1]], verts[f[0]]), sub3(verts[f[2]], verts[f[0]]));
    const L = Math.hypot(n[0], n[1], n[2]) || 1;
    const nn: Vec3 = [n[0] / L, n[1] / L, n[2] / L];
    vis[i] = dot3(nn, V) > 1e-6;
    if (!vis[i]) return;
    const d = poly(f.map((k) => scr[k]));
    if (nn[2] > 0.6) tops.push(d);
    else {
      const g = Math.hypot(nn[0], nn[1]) || 1;
      buckets[Math.min(SHADES - 1, Math.floor(light(nn[0] / g, nn[1] / g) * SHADES))].push(d);
    }
    for (let k = 0; k < f.length; k++) {
      const a = f[k], b = f[(k + 1) % f.length];
      const key = a < b ? a + "," + b : b + "," + a;
      edgeCount.set(key, (edgeCount.get(key) ?? 0) + 1);
    }
  });
  const crease: string[] = [];
  for (const [key, n] of edgeCount) if (n === 2) { const [a, b] = key.split(",").map(Number); crease.push(seg(scr[a], scr[b])); }
  return { sil: poly(hull(scr)), shades: buckets.map((b) => b.join("")), top: tops.join(""), crease: crease.join("") };
}

/**
 * A box of half-extents (hx, hy, hz), turned by R about its own centre and
 * placed at `c`. Optionally pivoted: `pivot` is a point in the box's own
 * frame that stays at `c` instead of the centre (a lever turning on its foot).
 */
export function cuboid(c: Vec3, hx: number, hy: number, hz: number, R: Rot = IDENT, pivot: Vec3 = [0, 0, 0]) {
  const local: Vec3[] = [
    [-hx, -hy, -hz], [hx, -hy, -hz], [hx, hy, -hz], [-hx, hy, -hz],
    [-hx, -hy, hz], [hx, -hy, hz], [hx, hy, hz], [-hx, hy, hz],
  ];
  const verts = local.map((v) => add3(c, turn(R, sub3(v, pivot))));
  const faces = [[0, 3, 2, 1], [4, 5, 6, 7], [0, 1, 5, 4], [1, 2, 6, 5], [2, 3, 7, 6], [3, 0, 4, 7]];
  return { verts, faces };
}

/** A prism from a convex ring in the box's own x–y plane, extruded ±hz, then turned and placed like `cuboid`. */
export function prism3(c: Vec3, ring: readonly Vec2[], hz: number, R: Rot = IDENT, pivot: Vec3 = [0, 0, 0]) {
  const n = ring.length;
  const local: Vec3[] = [...ring.map((p): Vec3 => [p[0], p[1], -hz]), ...ring.map((p): Vec3 => [p[0], p[1], hz])];
  const verts = local.map((v) => add3(c, turn(R, sub3(v, pivot))));
  const faces: number[][] = [Array.from({ length: n }, (_, k) => n - 1 - k), Array.from({ length: n }, (_, k) => n + k)];
  for (let k = 0; k < n; k++) faces.push([k, (k + 1) % n, n + (k + 1) % n, n + k]);
  return { verts, faces };
}

/* Adapted from Hairline (MIT, Lucas Marques): springs and the lift curve. */
import { clamp } from "./iso";
let reduced = false;
export const setReducedMotion = (on: boolean) => { reduced = on; };
export const reducedMotion = () => reduced;

export type Spring = { x: number; v: number; t: number; k: number; c: number; m: number; eps: number };
export type SpringOptions = { k?: number; c?: number; m?: number; eps?: number };

/** A spring at rest on x. k 100 · c 18 · m 1 unless told otherwise; `eps` is when it counts as settled. */
export function spring(x: number, o: SpringOptions = {}): Spring {
  return { x, v: 0, t: x, k: o.k ?? 100, c: o.c ?? 18, m: o.m ?? 1, eps: o.eps ?? 0.01 };
}

/**
 * Advances a spring by dt seconds toward `sp.t`, substepped at 240 Hz so a
 * long frame can't make it overshoot. Returns whether it is still moving.
 */
export function stepS(sp: Spring, dt: number): boolean {
  if (reduced) { sp.x = sp.t; sp.v = 0; return false; }
  const n = Math.max(1, Math.ceil(dt * 240)), h = dt / n;
  for (let i = 0; i < n; i++) {
    const a = (-sp.k * (sp.x - sp.t) - sp.c * sp.v) / sp.m;
    sp.v += a * h; sp.x += sp.v * h;
  }
  if (Math.abs(sp.x - sp.t) < sp.eps && Math.abs(sp.v) < sp.eps * 10) { sp.x = sp.t; sp.v = 0; return false; }
  return true;
}

/** A CSS cubic-bezier as a function of progress: Newton first, bisection if it strays. */
export function bezier(x1: number, y1: number, x2: number, y2: number): (t: number) => number {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const X = (u: number) => ((ax * u + bx) * u + cx) * u;
  const Y = (u: number) => ((ay * u + by) * u + cy) * u;
  const dX = (u: number) => (3 * ax * u + 2 * bx) * u + cx;
  return (t) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    let u = t;
    for (let i = 0; i < 8; i++) {
      const e = X(u) - t;
      if (Math.abs(e) < 1e-5) break;
      const d = dX(u);
      if (Math.abs(d) < 1e-6) break;
      u -= e / d;
    }
    if (!(u >= 0 && u <= 1) || Math.abs(X(u) - t) > 1e-4) {
      let lo = 0, hi = 1;
      u = t;
      for (let i = 0; i < 24; i++) { if (X(u) < t) lo = u; else hi = u; u = (lo + hi) / 2; }
    }
    return Y(u);
  };
}

/** Linear's lift curve, 700ms (.32, .72, 0, 1): the discrete clock. */
export const EASE_LIFT = bezier(0.32, 0.72, 0, 1);

/**
 * A tween on EASE_LIFT. `t0` is when it starts (it may be in the future: that
 * is how a stagger delays it), `dur` how long it runs, in ms of `now`.
 */
export type Tween = { from: number; to: number; t0: number; dur: number };
export const tween = (v: number, dur = 700): Tween => ({ from: v, to: v, t0: -1e9, dur });
/** Where the tween is at `now`. */
export const tval = (tw: Tween, now: number) => {
  const p = clamp((now - tw.t0) / tw.dur, 0, 1);
  return tw.from + (tw.to - tw.from) * (reduced ? 1 : EASE_LIFT(p));
};
/** Retargets from wherever it is now, starting after `delay` ms. A no-op if the target is unchanged. */
export const tset = (tw: Tween, to: number, now: number, delay: number) => {
  if (tw.to === to) return;
  tw.from = tval(tw, now); tw.to = to; tw.t0 = now + delay;
};
export const tdone = (tw: Tween, now: number) => reduced || now >= tw.t0 + tw.dur;

import { emit, nativeInput, num, snap, type BaseOptions, type EngineContext } from "./control";

/** Options every value control takes (Fader, Knob, Counter). */
export type RangeOptions = BaseOptions & {
  value?: number;
  defaultValue?: number;
  min?: number;
  max?: number;
  step?: number;
  /** Called with the new value on every change, by pointer, wheel or keyboard. */
  onValueChange?: (value: number) => void;
  /** Called once when a drag or key press settles. */
  onValueCommit?: (value: number) => void;
  /** Formats `aria-valuetext`, e.g. (v) => `${v} dB`. */
  format?: (value: number) => string;
  /** Set by the React wrapper when `value` is controlled. */
  controlled?: boolean;
};

export const RANGE_KEYS = ["value", "defaultValue", "min", "max", "step", "onValueChange", "onValueCommit", "format", "controlled"] as const;

export type Range = {
  readonly value: number;
  readonly min: number;
  readonly max: number;
  readonly step: number;
  /** 0…1 position of the value. */
  readonly t: number;
  input: HTMLInputElement;
  /** A request from the pointer or wheel; snapped, clamped, emitted. */
  ask(v: number): void;
  commit(): void;
  /** Applies new options; returns whether the value moved. */
  update(o: RangeOptions): boolean;
  destroy(): void;
};

/**
 * The value side of a range control, on a visually hidden native input of
 * `type` ("range" or "number"), so arrows, Page Up/Down, Home/End, screen
 * readers and form submission are the platform's own.
 */
export function range(ctx: EngineContext, o: RangeOptions, type: "range" | "number", label: string, onMove: () => void): Range {
  let opts = o;
  const lim = () => {
    const min = num(opts.min, 0), max = num(opts.max, 100);
    return { min: Math.min(min, max), max: Math.max(min, max), step: num(opts.step, 1) };
  };
  let { min, max, step } = lim();
  let value = snap(num(opts.value ?? opts.defaultValue, min), min, max, step);
  const input = nativeInput(ctx, { type });

  const sync = () => {
    input.min = String(min); input.max = String(max); input.step = String(step || "any");
    input.value = String(value);
    input.disabled = !!opts.disabled;
    input.setAttribute("aria-label", opts.label ?? label);
    if (opts.format) input.setAttribute("aria-valuetext", opts.format(value)); else input.removeAttribute("aria-valuetext");
    if (opts.name) input.name = opts.name; else input.removeAttribute("name");
  };
  sync();

  const ask = (v: number) => {
    const next = snap(v, min, max, step);
    if (next === value) { input.value = String(value); return; }
    if (opts.controlled) { input.value = String(value); emit(opts.onValueChange, next); return; }
    value = next; sync(); onMove(); emit(opts.onValueChange, next);
  };
  const onInput = () => ask(Number(input.value));
  const onChange = () => emit(opts.onValueCommit, value);
  input.addEventListener("input", onInput);
  input.addEventListener("change", onChange);

  return {
    get value() { return value; },
    get min() { return min; },
    get max() { return max; },
    get step() { return step; },
    get t() { return max > min ? (value - min) / (max - min) : 0; },
    input,
    ask,
    commit: onChange,
    update(next) {
      opts = next;
      ({ min, max, step } = lim());
      const want = snap(num(next.value, value), min, max, step);
      const moved = want !== value;
      value = want;
      sync();
      return moved;
    },
    destroy() {
      input.removeEventListener("input", onInput);
      input.removeEventListener("change", onChange);
      input.remove();
    },
  };
}

import { r2, type SolidPaths, type Vec2 } from "./iso";
import { setReducedMotion } from "./motion";

/**
 * Knurl — the DOM side every control shares: svg nodes, the solid's seven
 * paths, one frame loop for every control on the page (asleep offscreen and
 * at rest), and the only reduced-motion query. The loop's shape follows
 * Hairline's stage (MIT, Lucas Marques).
 *
 * Nothing here touches `window` at import, so the module is safe to evaluate
 * during a server render.
 */

const NS = "http://www.w3.org/2000/svg";
export type Attrs = Record<string, string | number>;

export function mk<K extends keyof SVGElementTagNameMap>(tag: K, attrs?: Attrs | null, parent?: Element | null): SVGElementTagNameMap[K] {
  const e = document.createElementNS(NS, tag);
  if (attrs) for (const k in attrs) e.setAttribute(k, String(attrs[k]));
  if (parent) parent.appendChild(e);
  return e;
}

/** A solid in the DOM: shadow, silhouette fill, four shade bands, lid, crease and outline. */
export type Solid = {
  g: SVGGElement;
  put(s: SolidPaths): void;
  /** Mark the solid as the lit one: a brighter outline and lid. */
  lit(on: boolean): void;
};

export function solid(parent: Element, cls = ""): Solid {
  const g = mk("g", { class: ("k-solid " + cls).trim() }, parent);
  const fill = mk("path", { class: "k-fill" }, g);
  const sh = [0, 1, 2, 3].map((i) => mk("path", { class: "k-shade", "data-s": i }, g));
  const top = mk("path", { class: "k-top" }, g);
  const cr = mk("path", { class: "k-crease" }, g);
  const edge = mk("path", { class: "k-edge" }, g);
  let last = "";
  return {
    g,
    put(s) {
      const key = s.sil + s.crease;
      if (key === last) return;
      last = key;
      fill.setAttribute("d", s.sil);
      edge.setAttribute("d", s.sil);
      sh.forEach((p, i) => p.setAttribute("d", s.shades[i]));
      top.setAttribute("d", s.top);
      cr.setAttribute("d", s.crease);
    },
    lit(on) { g.classList.toggle("k-lit", on); },
  };
}

/** A line or set of lines with a tone class: `hi`, `edge`, `mid`, `lo`. */
export const line = (parent: Element, tone = "mid", extra = "") => mk("path", { class: `k-line ${tone} ${extra}`.trim() }, parent);

/** A soft contact shadow under a footprint (solid finish only). */
export const shadow = (parent: Element, d: string) => mk("path", { class: "k-shadow", d }, parent);

export const setD = (el: SVGElement, d: string) => { if (el.getAttribute("d") !== d) el.setAttribute("d", d); };
export const place = (el: SVGElement, q: Vec2) => { el.setAttribute("cx", String(r2(q[0]))); el.setAttribute("cy", String(r2(q[1]))); };

/* ───── one loop ───── */

export type Tick = (dt: number, now: number) => boolean | void;
export type Loop = { wake(): void; unregister(): void };
type Board = { el: Element; tick: Tick; vis: boolean; awake: boolean };

let boards: Board[] = [];
let raf = 0, last = 0;
let io: IntersectionObserver | null = null;
let rm: MediaQueryList | null = null;

function frame() {
  const now = performance.now();
  const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
  last = now;
  let any = false;
  for (const b of boards.slice()) if (b.vis && b.awake) {
    try { b.awake = !!b.tick(dt, now); } catch (err) { b.awake = false; setTimeout(() => { throw err; }); }
    any = any || b.awake;
  }
  raf = any ? requestAnimationFrame(frame) : 0;
}

function wake(b: Board) {
  b.awake = true;
  if (!raf) { last = performance.now(); raf = requestAnimationFrame(frame); }
}

const onMotion = () => { setReducedMotion(!!rm?.matches); boards.forEach(wake); };

function start() {
  if (io) return;
  if (typeof IntersectionObserver !== "undefined") {
    io = new IntersectionObserver((es) => {
      for (const e of es) for (const b of boards) if (b.el === e.target) { b.vis = e.isIntersecting; if (b.vis) wake(b); }
    }, { rootMargin: "80px" });
  }
  if (typeof matchMedia !== "undefined") {
    rm = matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(rm.matches);
    rm.addEventListener?.("change", onMotion);
  }
}

function stop() {
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
  io?.disconnect(); io = null;
  rm?.removeEventListener?.("change", onMotion); rm = null;
}

/** Joins the shared loop. The tick runs once now, then each frame while the element is near the viewport and the tick returns true. */
export function register(el: Element, tick: Tick): Loop {
  start();
  const b: Board = { el, tick, vis: !io, awake: true };
  boards.push(b);
  io?.observe(el);
  tick(0, typeof performance !== "undefined" ? performance.now() : 0);
  let gone = false;
  return {
    wake: () => { if (!gone) wake(b); },
    unregister: () => {
      if (gone) return;
      gone = true;
      boards = boards.filter((x) => x !== b);
      if (!boards.some((x) => x.el === el)) io?.unobserve(el);
      if (!boards.length) stop();
    },
  };
}

/* ───── tear-down ───── */

export type Disposer = {
  add(fn: () => void): void;
  on<K extends keyof HTMLElementEventMap>(t: EventTarget, type: K, fn: (e: HTMLElementEventMap[K]) => void, opts?: AddEventListenerOptions): void;
  dispose(): void;
};

export function disposer(): Disposer {
  let fns: Array<() => void> = [];
  return {
    add: (fn) => { fns.push(fn); },
    on: (t, type, fn, opts) => {
      const h = fn as EventListener;
      t.addEventListener(type, h, opts);
      fns.push(() => t.removeEventListener(type, h, opts));
    },
    dispose: () => { const run = fns; fns = []; for (let i = run.length - 1; i >= 0; i--) run[i](); },
  };
}

/** The pointer in viewBox units. */
export function toView(svg: SVGSVGElement, e: { clientX: number; clientY: number }, vw: number, vh: number): Vec2 {
  const r = svg.getBoundingClientRect();
  return [((e.clientX - r.left) / (r.width || 1)) * vw, ((e.clientY - r.top) / (r.height || 1)) * vh];
}

/**
 * Knurl — the stylesheet, as a string, and the one function that injects it.
 *
 * Every selector sits inside `:where()`, so each rule has zero specificity and
 * any rule of the page wins without `!important` (Hairline's approach).
 * The `--knurl-*` properties are the public theme; `--k-*` are private and read
 * them with the palette as the fallback.
 *
 * Two finishes from the same geometry:
 *  - `line`  — hairlines over plates filled with the page colour (Hairline);
 *  - `solid` — four-tone shaded sides, lighter lids, a soft contact shadow (Anatomy).
 */

const LIGHT = {
  plate: "#ffffff", hi: "#1d1d20", edge: "#9d9da6", mid: "#c3c3c9", lo: "#e2e2e6",
  top: "#ffffff", s0: "#d9d9d6", s1: "#e3e3e0", s2: "#ecece9", s3: "#f5f5f2", shadow: "#6f6f66", "shadow-o": "0.28",
  accent: "#f76b15",
};
const DARK = {
  plate: "#09090b", hi: "#e4e6eb", edge: "#5d5f66", mid: "#3d3e44", lo: "#26272b",
  top: "#202024", s0: "#0e0e10", s1: "#121214", s2: "#161619", s3: "#1b1b1e", shadow: "#000000", "shadow-o": "0.75",
  accent: "#ff8a3d",
};
const KEYS = Object.keys(LIGHT) as (keyof typeof LIGHT)[];
type Palette = Record<(typeof KEYS)[number], string>;

const vars = (p: Palette) => KEYS.map((k) => `--k-${k}:var(--knurl-${k},${p[k]});`).join("");
const EASE = "cubic-bezier(0.32,0.72,0,1)";
const H = ":where([data-knurl])";
const S = ":where([data-knurl]>svg)";
const SOLID = ':where([data-knurl][data-knurl-finish="solid"]>svg)';

